import fse from 'fs-extra';
import path from 'path';
export const PACKAGE_ROUTE_PREFIX = '/_mintlify/pkg';
const BUILD_ID = /^[A-Za-z0-9_-]{1,64}$/;
const ISLAND_ENTRY = /^client\/islands\/([A-Za-z0-9_-]{1,64})\.js$/;
export const EMPTY_ISLAND_MODULE = 'export function hydrate() {\n  return { unmount() {} };\n}\n';
const resolveInside = (root, relative) => {
    const resolved = path.resolve(root, relative);
    return resolved.startsWith(root + path.sep) ? resolved : undefined;
};
export const createPackageRoute = (getState) => async (req, res, next) => {
    const state = getState();
    if (!state.enabled || (req.method !== 'GET' && req.method !== 'HEAD')) {
        next();
        return;
    }
    const [buildId, ...rest] = req.path.replace(/^\/+/, '').split('/');
    const relative = rest.join('/');
    const clientDir = buildId && BUILD_ID.test(buildId) ? path.join(state.buildsDir, buildId, 'client') : '';
    const inClient = relative.startsWith('client/') ? relative.slice('client/'.length) : '';
    const file = clientDir && inClient ? resolveInside(clientDir, inClient) : undefined;
    res.setHeader('X-Content-Type-Options', 'nosniff');
    if (file &&
        (await fse.stat(file).then((stat) => stat.isFile(), () => false))) {
        res.sendFile(path.relative(clientDir, file), {
            root: clientDir,
            dotfiles: 'deny',
            headers: { 'Cache-Control': 'no-cache' },
        });
        return;
    }
    if (ISLAND_ENTRY.test(relative)) {
        res
            .status(200)
            .type('text/javascript')
            .setHeader('Cache-Control', 'no-store')
            .send(EMPTY_ISLAND_MODULE);
        return;
    }
    res.status(404).type('text/plain').send('Not found');
};
